// Review probes: real git commit modes outside TestTrailerAuthority_RealGitCommits.
func TestReviewProbe_RealGitModes(t *testing.T) {
	t.Parallel()
	editors := t.TempDir()
	writeScripts(t, editors, map[string]string{
		"type": "#!/bin/sh\n{ printf 'Typed '; cat \"$1\"; } > \"$1.typed\" && mv \"$1.typed\" \"$1\"\n",
		// Types a subject and a body paragraph at the very end of the file.
		"body-below": "#!/bin/sh\n{ printf 'Typed\\n'; cat \"$1\"; printf '\\nBody typed below everything.\\n'; } > \"$1.typed\" && mv \"$1.typed\" \"$1\"\n",
		// Types a subject and deletes the Entire trailer line (user unlinks).
		"unlink": "#!/bin/sh\n{ printf 'Typed'; grep -v '^Entire-Checkpoint:' \"$1\"; } > \"$1.typed\" && mv \"$1.typed\" \"$1\"\n",
	})
	keep := "GIT_EDITOR=true"
	ed := func(name string) string {
		return "GIT_EDITOR=" + shellQuote(filepath.ToSlash(filepath.Join(editors, name)))
	}
	files := t.TempDir()
	template := filepath.Join(files, "template")
	require.NoError(t, os.WriteFile(template, []byte("Subject\n\n#42 is the issue\n"), 0o600))
	conventional := filepath.Join(files, "conventional")
	require.NoError(t, os.WriteFile(conventional, []byte("\n\n# <type>(<scope>): <subject>\n# Why this change:\n"), 0o600))

	type probe struct {
		name   string
		config map[string]string
		setup  func(env *TestEnv, git func([]string, ...string) (string, error))
		commit []string
		editor string
		prefix string
		// wantUnlinked: the user removed the trailer, nothing should link.
		wantUnlinked bool
	}
	commitLinked := func(env *TestEnv, git func([]string, ...string) (string, error), path, message string) string {
		env.T.Helper()
		authorityAgentTurn(env, path, "work on "+path+"\n")
		_, err := git(nil, "add", path)
		require.NoError(env.T, err)
		out, err := git(nil, "commit", "--no-gpg-sign", "-m", message)
		require.NoError(env.T, err, out)
		ids := trailers.ParseAllCheckpoints(env.GetCommitMessage(env.GetHeadHash()))
		require.Len(env.T, ids, 1)
		return ids[0].String()
	}
	squashSetup := func(env *TestEnv, git func([]string, ...string) (string, error)) {
		_, err := git(nil, "checkout", "-q", "-b", "side")
		require.NoError(env.T, err)
		commitLinked(env, git, "side.txt", "Side work")
		_, err = git(nil, "checkout", "-q", "feature/test-branch")
		require.NoError(env.T, err)
		out, err := git(nil, "merge", "--squash", "side")
		require.NoError(env.T, err, out)
	}
	probes := []probe{
		{name: "merge --squash then editor", setup: squashSetup, editor: ed("type")},
		{name: "merge --squash then --no-edit", setup: squashSetup, commit: []string{"--no-edit"}},
		{name: "-s in the editor", commit: []string{"-s"}, editor: ed("type")},
		{name: "-v in the editor", commit: []string{"-v"}, editor: ed("type")},
		{name: "commit.verbose in the editor", config: map[string]string{"commit.verbose": "true"}, editor: ed("type")},
		{name: "-c core.commentChar=; on the command line", commit: nil, editor: ed("type"), prefix: ";"},
		{name: "--cleanup=whitespace flag under auto with # template", config: map[string]string{"core.commentChar": "auto"}, commit: []string{"--cleanup=whitespace", "-t", template}, editor: ed("type")},
		{name: "--cleanup=scissors flag under auto with # template", config: map[string]string{"core.commentChar": "auto"}, commit: []string{"--cleanup=scissors", "-t", template}, editor: ed("type")},
		{name: "--cleanup=whitespace flag, default #", commit: []string{"--cleanup=whitespace"}, editor: ed("type")},
		{name: "conventional template with comment lines", commit: []string{"-t", conventional}, editor: ed("type")},
		{name: "--trailer in the editor", commit: []string{"--trailer", "Co-authored-by: A <a@example.com>"}, editor: ed("type")},
		{name: "--trailer with -m", commit: []string{"--trailer", "Co-authored-by: A <a@example.com>", "-m", "Fix login"}},
		{name: "body typed below the trailer", editor: ed("body-below")},
		{name: "user deletes the trailer", editor: ed("unlink"), wantUnlinked: true},
		{
			name: "--fixup=HEAD",
			setup: func(env *TestEnv, git func([]string, ...string) (string, error)) {
				commitLinked(env, git, "first.txt", "First")
			},
			commit: []string{"--fixup=HEAD"},
		},
		{
			name: "-c HEAD reedit of a linked commit",
			setup: func(env *TestEnv, git func([]string, ...string) (string, error)) {
				commitLinked(env, git, "first.txt", "First")
			},
			commit: []string{"-c", "HEAD"},
			editor: keep,
		},
	}
	for _, p := range probes {
		t.Run(p.name, func(t *testing.T) {
			t.Parallel()
			env := NewFeatureBranchEnv(t)
			git := gitWithEntireCommitHooksEnv(t, env)
			for k, v := range p.config {
				setRepoGitConfig(env, k, v)
			}
			if p.setup != nil {
				p.setup(env, git)
			}
			authorityAgentTurn(env, "mine.txt", "my agent work\n")
			_, err := git(nil, "add", "mine.txt")
			require.NoError(t, err)
			editor := p.editor
			if editor == "" {
				editor = keep
			}
			args := []string{"commit", "--no-gpg-sign"}
			if p.name == "-c core.commentChar=; on the command line" {
				args = []string{"-c", "core.commentChar=;", "commit", "--no-gpg-sign"}
			}
			out, err := git([]string{editor}, append(args, p.commit...)...)
			require.NoError(t, err, out)
			recorded := env.GetCommitMessage(env.GetHeadHash())
			prefix := p.prefix
			if prefix == "" {
				prefix = "#"
			}
			all := trailers.ParseAllCheckpoints(recorded)
			final := trailers.ParseAllCheckpointsFromFinalTrailerBlock(recorded, prefix)
			stored := map[string]bool{}
			for _, id := range all {
				stored[id.String()] = advCheckpointStored(env, id.String())
			}
			t.Logf("RECORDED %q\n  all=%v final=%v stored=%v", recorded, all, final, stored)
			if p.wantUnlinked {
				if len(all) != 0 {
					t.Errorf("PROBE: user removed the trailer but the commit still carries %v", all)
				}
				return
			}
			if len(final) == 0 {
				t.Errorf("PROBE: no checkpoint in the final trailer block")
				return
			}
			if !stored[final[len(final)-1].String()] {
				t.Errorf("PROBE: final block's last checkpoint %s not stored", final[len(final)-1])
			}
			if strings.Contains(recorded, "Remove the Entire-Checkpoint trailer") {
				t.Errorf("PROBE: Entire's explanation recorded in the commit")
			}
		})
	}
}

